// covert a calendar object to a local timestamp (epoch, but with the offset baked in)
export function objToLocalTS(obj) {
  // for legacy reasons, years between 0 and 99 are interpreted as 19XX. Compute the
  // timestamp for a year 400 years later instead (the Gregorian calendar repeats
  // exactly every 400 years, so the calendar -- including any overflowed days or
  // months -- is identical) and then shift the resulting timestamp back.
  const shifted = obj.year >= 0 && obj.year < 100,
    d = Date.UTC(
      shifted ? obj.year + 400 : obj.year,
      obj.month - 1,
      obj.day,
      obj.hour,
      obj.minute,
      obj.second,
      obj.millisecond
    );

  return shifted ? d - 400 * 146097 * 86400000 : d;
}

